// Local stand-in for a self-hosted OpenSubsonic music server (what Feishin normally talks to),
// plus static hosting of the Feishin web build. Zero dependencies; Node built-ins only.
//   - /rest/*.view   OpenSubsonic API backed by data/library.json (generated by seed.mjs)
//   - /rest/getCoverArt.view  generated SVG artwork (no real audio files / images exist)
//   - /rest/stream.view       silent WAV of the right length so playback works offline
//   - /settings.js   Feishin's deploy-time config (same file the Docker image templates)
//   - everything else: the static web build with SPA fallback
import { createHash } from 'node:crypto';
import { existsSync, readFileSync, statSync } from 'node:fs';
import http from 'node:http';
import { dirname, extname, join, normalize } from 'node:path';
import { fileURLToPath } from 'node:url';

const HERE = dirname(fileURLToPath(import.meta.url));
const WEB = join(HERE, 'web');
const PORT = Number(process.env.PORT || 4427);
const lib = JSON.parse(readFileSync(join(HERE, 'data', 'library.json'), 'utf8'));

const USER = lib.user;
const md5 = (s) => createHash('md5').update(s).digest('hex');
const iso = (t) => (t == null ? undefined : new Date(t).toISOString().replace(/\.\d+Z$/, 'Z'));

const artistById = new Map(lib.artists.map((a) => [a.id, a]));
const albumById = new Map(lib.albums.map((a) => [a.id, a]));
const songById = new Map(lib.songs.map((s) => [s.id, s]));
const playlistById = new Map(lib.playlists.map((p) => [p.id, p]));
const radioById = new Map(lib.radio.map((r) => [r.id, r]));
const albumArtists = lib.artists.filter((a) => a.isAlbumArtist);

// ---------- serializers (OpenSubsonic JSON shapes) ----------
const simpleArtist = (a) => ({ id: a.id, name: a.name });
const genreName = (album) => album.genres[0];

function songJson(s) {
    const al = albumById.get(s.albumId);
    const aa = artistById.get(al.artistId);
    const arts = s.artistIds.map((id) => artistById.get(id));
    const display = arts.length > 1 ? `${arts[0].name} feat. ${arts.slice(1).map((a) => a.name).join(', ')}` : arts[0].name;
    return {
        id: s.id,
        parent: s.albumId,
        isDir: false,
        title: s.title,
        album: al.name,
        artist: display,
        track: s.track,
        year: al.year || undefined,
        genre: s.genre,
        coverArt: al.id,
        size: s.size,
        contentType: s.contentType,
        suffix: s.suffix,
        duration: s.duration,
        bitRate: s.bitRate,
        bitDepth: s.bitDepth,
        samplingRate: s.samplingRate,
        channelCount: 2,
        path: s.path,
        playCount: s.playCount || 0,
        played: iso(s.played),
        discNumber: s.discNumber,
        created: iso(s.created),
        albumId: s.albumId,
        artistId: arts[0].id,
        type: 'music',
        mediaType: 'song',
        isVideo: false,
        bpm: s.bpm || 0,
        comment: '',
        sortName: s.title,
        starred: iso(s.starred),
        userRating: s.userRating,
        genres: s.genre ? [{ name: s.genre }] : [],
        artists: arts.map(simpleArtist),
        displayArtist: display,
        albumArtists: [simpleArtist(aa)],
        displayAlbumArtist: aa.name,
        contributors: [],
        replayGain: s.replayGain || {},
        explicitStatus: al.artist === 'Kendrick Lamar' ? 'explicit' : '',
    };
}

function albumJson(al, withSongs = false) {
    const aa = artistById.get(al.artistId);
    const ss = al.songIds.map((id) => songById.get(id));
    const out = {
        id: al.id,
        parent: al.artistId,
        isDir: true,
        title: al.name,
        name: al.name,
        album: al.name,
        artist: al.artist,
        artistId: al.artistId,
        year: al.year || undefined,
        genre: genreName(al),
        coverArt: al.id,
        songCount: ss.length,
        duration: ss.reduce((n, s) => n + s.duration, 0),
        playCount: al.playCount || 0,
        played: iso(al.played),
        created: iso(al.created),
        starred: iso(al.starred),
        userRating: al.userRating,
        isVideo: false,
        isCompilation: false,
        artists: [simpleArtist(aa)],
        displayArtist: al.artist,
        genres: al.genres.map((name) => ({ name })),
        recordLabels: al.label ? [{ name: al.label }] : [],
        releaseTypes: ['Album'],
        sortName: al.name,
        musicBrainzId: '',
        explicitStatus: al.artist === 'Kendrick Lamar' ? 'explicit' : '',
        version: '',
        discTitles: [],
    };
    if (withSongs) out.song = ss.map(songJson);
    return out;
}

function artistJson(a, withAlbums = false) {
    const out = {
        id: a.id,
        name: a.name,
        coverArt: 'ar-' + a.id,
        artistImageUrl: `/rest/getCoverArt.view?id=ar-${a.id}&size=600`,
        albumCount: a.albumIds.length,
        starred: iso(a.starred),
        roles: a.isAlbumArtist ? ['albumartist', 'artist'] : ['artist'],
        sortName: a.name.replace(/^The /, ''),
    };
    if (withAlbums) out.album = a.albumIds.map((id) => albumJson(albumById.get(id)));
    return out;
}

function playlistJson(p, withEntries = false) {
    const ss = p.songs.map((id) => songById.get(id)).filter(Boolean);
    const out = {
        id: p.id,
        name: p.name,
        comment: p.comment || undefined,
        owner: p.owner,
        public: p.public,
        songCount: ss.length,
        duration: ss.reduce((n, s) => n + s.duration, 0),
        created: iso(p.created),
        changed: iso(p.changed),
        coverArt: 'pl-' + p.id,
        readonly: false,
    };
    if (withEntries) out.entry = ss.map(songJson);
    return out;
}

// ---------- helpers ----------
const arr = (v) => (v == null ? [] : Array.isArray(v) ? v : [v]);
const num = (v, d) => (v == null || v === '' ? d : Number(v));
const shuffle = (a) => {
    const c = [...a];
    for (let i = c.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [c[i], c[j]] = [c[j], c[i]];
    }
    return c;
};
// Bracketed placeholders like [Unknown Artist] sort after real names, as Navidrome does.
const sk = (s) => (s.startsWith('[') ? '\uffff' + s : s.replace(/^The /, ''));
const cmp = (a, b) => sk(a).localeCompare(sk(b), 'en', { sensitivity: 'base' });
const matches = (q, ...fields) => {
    const terms = q.toLowerCase().replace(/["*]/g, '').trim().split(/\s+/).filter(Boolean);
    const hay = fields.filter(Boolean).join(' ').toLowerCase();
    return terms.every((t) => hay.includes(t));
};

function checkAuth(p) {
    if (p.u !== USER.username) return false;
    if (p.t && p.s) return md5(USER.password + p.s) === p.t;
    if (p.p) {
        const pw = p.p.startsWith('enc:') ? Buffer.from(p.p.slice(4), 'hex').toString() : p.p;
        return pw === USER.password;
    }
    return false;
}

const ok = (body = {}) => ({
    'subsonic-response': { status: 'ok', version: '1.16.1', type: 'navidrome', serverVersion: '0.58.0 (local)', openSubsonic: true, ...body },
});
const fail = (code, message) => ({
    'subsonic-response': { status: 'failed', version: '1.16.1', type: 'navidrome', serverVersion: '0.58.0 (local)', openSubsonic: true, error: { code, message } },
});

// ---------- API ----------
const api = {
    ping: () => ok(),
    getLicense: () => ok({ license: { valid: true } }),
    getOpenSubsonicExtensions: () =>
        ok({ openSubsonicExtensions: [{ name: 'songLyrics', versions: [1] }, { name: 'formPost', versions: [1] }, { name: 'topSongsByArtistId', versions: [1] }, { name: 'indexBasedQueue', versions: [1] }] }),
    getUser: () =>
        ok({
            user: {
                username: USER.username, email: USER.email, scrobblingEnabled: true, adminRole: true, settingsRole: true, downloadRole: true,
                uploadRole: false, playlistRole: true, coverArtRole: true, commentRole: true, podcastRole: false, streamRole: true,
                jukeboxRole: false, shareRole: true, videoConversionRole: false, folder: [1],
            },
        }),
    getMusicFolders: () => ok({ musicFolders: { musicFolder: [lib.folder] } }),
    getScanStatus: () => ok({ scanStatus: { scanning: false, count: lib.songs.length, folderCount: lib.albums.length + 1, lastScan: iso(Date.now() - 5 * 3600000) } }),
    startScan: () => ok({ scanStatus: { scanning: true, count: lib.songs.length, folderCount: lib.albums.length + 1 } }),
    jukeboxControl: () => fail(0, 'Jukebox is disabled'),
    getArtists: () => {
        const groups = new Map();
        for (const a of [...albumArtists].sort((x, y) => cmp(artistJson(x).sortName, artistJson(y).sortName))) {
            const sn = artistJson(a).sortName;
            const ch = /^[a-z]/i.test(sn) ? sn[0].toUpperCase() : '#';
            if (!groups.has(ch)) groups.set(ch, []);
            groups.get(ch).push(artistJson(a));
        }
        return ok({ artists: { ignoredArticles: 'The El La Los Las Le Les', index: [...groups].map(([name, artist]) => ({ name, artist })) } });
    },
    getIndexes: () => {
        const groups = new Map();
        for (const a of [...albumArtists].sort((x, y) => cmp(x.name, y.name))) {
            const ch = /^[a-z]/i.test(a.name) ? a.name[0].toUpperCase() : '#';
            if (!groups.has(ch)) groups.set(ch, []);
            groups.get(ch).push({ id: a.id, name: a.name, coverArt: 'ar-' + a.id });
        }
        return ok({ indexes: { lastModified: Date.now(), ignoredArticles: 'The', shortcut: [], child: [], index: [...groups].map(([name, artist]) => ({ name, artist })) } });
    },
    getMusicDirectory: (p) => {
        if (artistById.has(p.id)) {
            const a = artistById.get(p.id);
            return ok({ directory: { id: a.id, name: a.name, title: a.name, isDir: true, parent: '1', child: a.albumIds.map((id) => albumJson(albumById.get(id))) } });
        }
        const al = albumById.get(p.id);
        if (!al) return fail(70, 'Directory not found');
        return ok({ directory: { id: al.id, name: al.name, title: al.name, isDir: true, parent: al.artistId, artist: al.artist, coverArt: al.id, child: al.songIds.map((id) => songJson(songById.get(id))) } });
    },
    getArtist: (p) => {
        const a = artistById.get(p.id);
        return a ? ok({ artist: artistJson(a, true) }) : fail(70, 'Artist not found');
    },
    getArtistInfo: (p) => api.getArtistInfo2(p),
    getArtistInfo2: (p) => {
        const a = artistById.get(p.id);
        if (!a) return fail(70, 'Artist not found');
        const genres = new Set(a.albumIds.flatMap((id) => albumById.get(id).genres));
        const similar = albumArtists
            .filter((x) => x.id !== a.id && x.albumIds.some((id) => albumById.get(id).genres.some((g) => genres.has(g))))
            .slice(0, num(p.count, 20))
            .map((x) => ({ id: x.id, name: x.name, albumCount: x.albumIds.length, coverArt: 'ar-' + x.id, artistImageUrl: `/rest/getCoverArt.view?id=ar-${x.id}&size=300` }));
        const img = (s) => `/rest/getCoverArt.view?id=ar-${a.id}&size=${s}`;
        return ok({
            artistInfo2: {
                biography: a.bio || '',
                musicBrainzId: '',
                lastFmUrl: '',
                smallImageUrl: img(150), mediumImageUrl: img(300), largeImageUrl: img(600),
                similarArtist: similar,
            },
        });
    },
    getAlbum: (p) => {
        const al = albumById.get(p.id);
        return al ? ok({ album: albumJson(al, true) }) : fail(70, 'Album not found');
    },
    getAlbumInfo: (p) => api.getAlbumInfo2(p),
    getAlbumInfo2: (p) => {
        const al = albumById.get(p.id);
        if (!al) return fail(70, 'Album not found');
        const img = (s) => `/rest/getCoverArt.view?id=${al.id}&size=${s}`;
        return ok({ albumInfo: { notes: '', musicBrainzId: '', lastFmUrl: '', smallImageUrl: img(150), mediumImageUrl: img(300), largeImageUrl: img(600) } });
    },
    getAlbumList: (p) => {
        const r = api.getAlbumList2(p);
        return ok({ albumList: { album: r['subsonic-response'].albumList2.album } });
    },
    getAlbumList2: (p) => {
        let list = [...lib.albums];
        const type = p.type || 'alphabeticalByName';
        switch (type) {
            case 'newest': list.sort((a, b) => b.created - a.created); break;
            case 'recent': list = list.filter((a) => a.played).sort((a, b) => b.played - a.played); break;
            case 'frequent': list = list.filter((a) => a.playCount).sort((a, b) => b.playCount - a.playCount); break;
            case 'starred': list = list.filter((a) => a.starred).sort((a, b) => cmp(a.name, b.name)); break;
            case 'random': list = shuffle(list); break;
            case 'highest': list = list.filter((a) => a.userRating).sort((a, b) => b.userRating - a.userRating); break;
            case 'alphabeticalByArtist': list.sort((a, b) => cmp(a.artist, b.artist) || a.year - b.year); break;
            case 'byGenre': list = list.filter((a) => a.genres.includes(p.genre)).sort((a, b) => cmp(a.name, b.name)); break;
            case 'byYear': {
                const from = num(p.fromYear, 0);
                const to = num(p.toYear, 9999);
                const lo = Math.min(from, to);
                const hi = Math.max(from, to);
                list = list.filter((a) => a.year >= lo && a.year <= hi).sort((a, b) => (from <= to ? a.year - b.year : b.year - a.year));
                break;
            }
            default: list.sort((a, b) => cmp(a.name, b.name));
        }
        const off = num(p.offset, 0);
        const size = num(p.size, 10);
        return ok({ albumList2: { album: list.slice(off, off + size).map((a) => albumJson(a)) } });
    },
    getSong: (p) => {
        const s = songById.get(p.id);
        return s ? ok({ song: songJson(s) }) : fail(70, 'Song not found');
    },
    getRandomSongs: (p) => {
        let list = lib.songs;
        if (p.genre) list = list.filter((s) => s.genre === p.genre);
        if (p.fromYear) list = list.filter((s) => albumById.get(s.albumId).year >= Number(p.fromYear));
        if (p.toYear) list = list.filter((s) => albumById.get(s.albumId).year <= Number(p.toYear));
        return ok({ randomSongs: { song: shuffle(list).slice(0, num(p.size, 10)).map(songJson) } });
    },
    getSongsByGenre: (p) => {
        const list = lib.songs.filter((s) => s.genre === p.genre || albumById.get(s.albumId).genres.includes(p.genre));
        const off = num(p.offset, 0);
        return ok({ songsByGenre: { song: list.slice(off, off + num(p.count, 10)).map(songJson) } });
    },
    getGenres: () => {
        const g = new Map();
        for (const al of lib.albums) {
            for (const name of al.genres) {
                if (!g.has(name)) g.set(name, { value: name, albumCount: 0, songCount: 0 });
                g.get(name).albumCount++;
                g.get(name).songCount += al.songIds.length;
            }
        }
        return ok({ genres: { genre: [...g.values()].sort((a, b) => cmp(a.value, b.value)) } });
    },
    search2: (p) => {
        const r = api.search3(p)['subsonic-response'].searchResult3;
        return ok({ searchResult2: r });
    },
    search3: (p) => {
        const q = (p.query || '').trim();
        const all = !q || q === '""';
        const artistsF = albumArtists.filter((a) => all || matches(q, a.name));
        const albumsF = lib.albums.filter((a) => all || matches(q, a.name, a.artist));
        let songsF = lib.songs.filter((s) => all || matches(q, s.title, albumById.get(s.albumId).name, albumById.get(s.albumId).artist));
        if (all) songsF = [...songsF].sort((a, b) => cmp(albumById.get(a.albumId).artist, albumById.get(b.albumId).artist) || cmp(albumById.get(a.albumId).name, albumById.get(b.albumId).name) || a.track - b.track);
        const sl = (list, off, cnt, d) => list.slice(num(off, 0), num(off, 0) + num(cnt, d));
        return ok({
            searchResult3: {
                artist: sl(artistsF, p.artistOffset, p.artistCount, 20).map((a) => artistJson(a)),
                album: sl(albumsF, p.albumOffset, p.albumCount, 20).map((a) => albumJson(a)),
                song: sl(songsF, p.songOffset, p.songCount, 20).map(songJson),
            },
        });
    },
    getStarred: (p) => {
        const r = api.getStarred2(p)['subsonic-response'].starred2;
        return ok({ starred: r });
    },
    getStarred2: () =>
        ok({
            starred2: {
                artist: lib.artists.filter((a) => a.starred).map((a) => artistJson(a)),
                album: lib.albums.filter((a) => a.starred).map((a) => albumJson(a)),
                song: lib.songs.filter((s) => s.starred).sort((a, b) => b.starred - a.starred).map(songJson),
            },
        }),
    star: (p) => {
        const t = Date.now();
        for (const id of [...arr(p.id), ...arr(p.albumId), ...arr(p.artistId)]) {
            const o = songById.get(id) || albumById.get(id) || artistById.get(id);
            if (o) o.starred = t;
        }
        return ok();
    },
    unstar: (p) => {
        for (const id of [...arr(p.id), ...arr(p.albumId), ...arr(p.artistId)]) {
            const o = songById.get(id) || albumById.get(id) || artistById.get(id);
            if (o) delete o.starred;
        }
        return ok();
    },
    setRating: (p) => {
        const o = songById.get(p.id) || albumById.get(p.id) || artistById.get(p.id);
        if (o) o.userRating = Number(p.rating) || undefined;
        return ok();
    },
    scrobble: (p) => {
        if (p.submission !== 'false') {
            for (const id of arr(p.id)) {
                const s = songById.get(id);
                if (s) {
                    s.playCount = (s.playCount || 0) + 1;
                    s.played = Date.now();
                    const al = albumById.get(s.albumId);
                    al.playCount = (al.playCount || 0) + 1;
                    al.played = s.played;
                }
            }
        }
        return ok();
    },
    getTopSongs: (p) => {
        const a = p.id ? artistById.get(p.id) : albumArtists.find((x) => x.name === p.artist);
        if (!a) return ok({ topSongs: { song: [] } });
        const list = lib.songs.filter((s) => s.artistIds.includes(a.id)).sort((x, y) => (y.playCount || 0) - (x.playCount || 0));
        return ok({ topSongs: { song: list.slice(0, num(p.count, 50)).map(songJson) } });
    },
    getSimilarSongs: (p) => {
        const r = api.getSimilarSongs2(p)['subsonic-response'].similarSongs2;
        return ok({ similarSongs: r });
    },
    getSimilarSongs2: (p) => {
        const base = songById.get(p.id) || albumById.get(p.id) || artistById.get(p.id);
        let genres = [];
        if (base?.albumId) genres = albumById.get(base.albumId).genres;
        else if (base?.genres) genres = base.genres;
        else if (base?.albumIds) genres = base.albumIds.flatMap((id) => albumById.get(id).genres);
        const pool = lib.songs.filter((s) => albumById.get(s.albumId).genres.some((g) => genres.includes(g)));
        return ok({ similarSongs2: { song: shuffle(pool).slice(0, num(p.count, 50)).map(songJson) } });
    },
    getLyricsBySongId: () => ok({ lyricsList: { structuredLyrics: [] } }),
    getLyrics: () => ok({ lyrics: {} }),
    getPlaylists: () => ok({ playlists: { playlist: [...lib.playlists].sort((a, b) => cmp(a.name, b.name)).map((p) => playlistJson(p)) } }),
    getPlaylist: (p) => {
        const pl = playlistById.get(p.id);
        return pl ? ok({ playlist: playlistJson(pl, true) }) : fail(70, 'Playlist not found');
    },
    createPlaylist: (p) => {
        let pl;
        if (p.playlistId) {
            pl = playlistById.get(p.playlistId);
            pl.songs = arr(p.songId);
        } else {
            pl = { id: md5('pl' + Date.now()).slice(0, 22), name: p.name || 'New Playlist', comment: '', public: false, owner: USER.username, created: Date.now(), songs: arr(p.songId) };
            lib.playlists.push(pl);
            playlistById.set(pl.id, pl);
        }
        pl.changed = Date.now();
        return ok({ playlist: playlistJson(pl, true) });
    },
    updatePlaylist: (p) => {
        const pl = playlistById.get(p.playlistId);
        if (!pl) return fail(70, 'Playlist not found');
        if (p.name != null) pl.name = p.name;
        if (p.comment != null) pl.comment = p.comment;
        if (p.public != null) pl.public = p.public === 'true';
        const rm = new Set(arr(p.songIndexToRemove).map(Number));
        pl.songs = pl.songs.filter((_, i) => !rm.has(i)).concat(arr(p.songIdToAdd));
        pl.changed = Date.now();
        return ok();
    },
    deletePlaylist: (p) => {
        lib.playlists = lib.playlists.filter((x) => x.id !== p.id);
        playlistById.delete(p.id);
        return ok();
    },
    getPlayQueue: () => {
        const q = lib.playQueue;
        return ok({ playQueue: { entry: q.ids.map((id) => songJson(songById.get(id))), current: q.ids[q.currentIndex], position: q.position, username: USER.username, changed: iso(q.changed), changedBy: q.changedBy } });
    },
    getPlayQueueByIndex: () => {
        const q = lib.playQueue;
        return ok({ playQueueByIndex: { entry: q.ids.map((id) => songJson(songById.get(id))), currentIndex: q.currentIndex, position: q.position, username: USER.username, changed: iso(q.changed), changedBy: q.changedBy } });
    },
    savePlayQueue: (p) => {
        const ids = arr(p.id);
        lib.playQueue = { ids, currentIndex: Math.max(0, ids.indexOf(p.current)), position: num(p.position, 0), changed: Date.now(), changedBy: p.c || 'Feishin' };
        return ok();
    },
    savePlayQueueByIndex: (p) => {
        lib.playQueue = { ids: arr(p.id), currentIndex: num(p.currentIndex, 0), position: num(p.position, 0), changed: Date.now(), changedBy: p.c || 'Feishin' };
        return ok();
    },
    getInternetRadioStations: () => ok({ internetRadioStations: { internetRadioStation: lib.radio } }),
    createInternetRadioStation: (p) => {
        const r = { id: md5('r' + Date.now()).slice(0, 12), name: p.name, streamUrl: p.streamUrl, homePageUrl: p.homepageUrl };
        lib.radio.push(r);
        radioById.set(r.id, r);
        return ok();
    },
    updateInternetRadioStation: (p) => {
        const r = radioById.get(p.id);
        if (r) Object.assign(r, { name: p.name ?? r.name, streamUrl: p.streamUrl ?? r.streamUrl, homePageUrl: p.homepageUrl ?? r.homePageUrl });
        return ok();
    },
    deleteInternetRadioStation: (p) => {
        lib.radio = lib.radio.filter((r) => r.id !== p.id);
        return ok();
    },
    getNowPlaying: () => ok({ nowPlaying: {} }),
    getShares: () => ok({ shares: { share: [] } }),
    getPodcasts: () => ok({ podcasts: { channel: [] } }),
};

// ---------- cover art (deterministic generated SVG) ----------
const PALETTES = [
    ['#0f2027', '#2c5364', '#f2c94c'], ['#2d1b4e', '#ff6b6b', '#ffd93d'], ['#1a1a2e', '#e94560', '#0f3460'],
    ['#f4e1c1', '#c75b39', '#2b2d42'], ['#0b3d2e', '#8fc1a9', '#f6f1d1'], ['#101010', '#e0e0e0', '#ff3c00'],
    ['#3a0ca3', '#f72585', '#4cc9f0'], ['#283618', '#dda15e', '#fefae0'], ['#14213d', '#fca311', '#e5e5e5'],
    ['#5f0f40', '#fb8b24', '#0f4c5c'], ['#e9d8a6', '#005f73', '#ae2012'], ['#22223b', '#9a8c98', '#f2e9e4'],
    ['#003049', '#d62828', '#fcbf49'], ['#6b705c', '#ffe8d6', '#cb997e'], ['#1b263b', '#778da9', '#e0e1dd'],
    ['#ff99c8', '#a9def9', '#3d348b'], ['#000000', '#7b2cbf', '#e0aaff'], ['#386641', '#f2e8cf', '#bc4749'],
];
const esc = (s) => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
function hashBytes(s) {
    return createHash('sha256').update(s).digest();
}
function wrap(text, max) {
    const words = text.split(/\s+/);
    const lines = [];
    let cur = '';
    for (const w of words) {
        if ((cur + ' ' + w).trim().length > max && cur) {
            lines.push(cur);
            cur = w;
        } else cur = (cur + ' ' + w).trim();
    }
    if (cur) lines.push(cur);
    return lines.slice(0, 4);
}
function coverSvg(key, title, subtitle, kind) {
    const h = hashBytes(key);
    const [bg, fg, ac] = PALETTES[h[0] % PALETTES.length];
    const style = kind === 'artist' ? 9 : h[1] % 6;
    let art = '';
    if (style === 0) {
        for (let i = 0; i < 7; i++) art += `<circle cx="${(h[2 + i] / 255) * 600}" cy="${(h[9 + i] / 255) * 600}" r="${40 + (h[16 + i] % 160)}" fill="${i % 2 ? fg : ac}" opacity="${0.25 + (h[20 + (i % 8)] % 60) / 100}"/>`;
    } else if (style === 1) {
        const n = 6 + (h[2] % 10);
        for (let i = 0; i < n; i++) art += `<rect x="0" y="${(600 / n) * i}" width="600" height="${600 / n / 2}" fill="${i % 3 === 0 ? ac : fg}" opacity="0.8" transform="rotate(${(h[3] % 40) - 20} 300 300)"/>`;
    } else if (style === 2) {
        art = `<circle cx="300" cy="${260 + (h[2] % 60)}" r="${150 + (h[3] % 70)}" fill="${ac}"/><circle cx="300" cy="${260 + (h[2] % 60)}" r="${70 + (h[4] % 50)}" fill="${bg}"/>`;
    } else if (style === 3) {
        for (let x = 0; x < 6; x++) for (let y = 0; y < 6; y++) if (h[(x * 6 + y) % 32] % 3 === 0) art += `<rect x="${x * 100 + 6}" y="${y * 100 + 6}" width="88" height="88" fill="${(x + y) % 2 ? fg : ac}"/>`;
    } else if (style === 4) {
        let d = 'M0 600';
        for (let i = 0; i <= 12; i++) d += ` L${i * 50} ${250 + (h[i % 32] % 220)}`;
        art = `<path d="${d} L600 600 Z" fill="${fg}"/><circle cx="${120 + (h[5] % 360)}" cy="140" r="60" fill="${ac}"/>`;
    } else if (style === 5) {
        for (let i = 0; i < 14; i++) art += `<line x1="${h[i] * 2.35}" y1="0" x2="${h[i + 14] * 2.35}" y2="600" stroke="${i % 2 ? fg : ac}" stroke-width="${2 + (h[i + 3] % 18)}" opacity="0.85"/>`;
    } else {
        art = `<circle cx="300" cy="250" r="120" fill="${fg}" opacity="0.9"/><path d="M90 600 C120 420 480 420 510 600 Z" fill="${fg}" opacity="0.9"/>`;
    }
    const lines = wrap(title, 18);
    const txt =
        kind === 'artist'
            ? ''
            : `<g font-family="Helvetica, Arial, sans-serif" fill="${style === 2 ? fg : '#ffffff'}">${lines
                  .map((l, i) => `<text x="36" y="${470 + i * 40 - (lines.length - 1) * 40}" font-size="34" font-weight="700">${esc(l)}</text>`)
                  .join('')}<text x="36" y="560" font-size="22" opacity="0.85">${esc(subtitle || '')}</text></g>`;
    return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 600 600" width="600" height="600"><defs><linearGradient id="g" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="${bg}"/><stop offset="1" stop-color="${fg}" stop-opacity="0.35"/></linearGradient></defs><rect width="600" height="600" fill="${bg}"/><rect width="600" height="600" fill="url(#g)"/>${art}${kind === 'artist' ? '' : '<rect y="380" width="600" height="220" fill="#000" opacity="0.28"/>'}${txt}</svg>`;
}
function coverFor(id) {
    if (id.startsWith('ar-')) {
        const a = artistById.get(id.slice(3));
        return a ? coverSvg('artist' + a.id, a.name, '', 'artist') : null;
    }
    if (id.startsWith('pl-')) {
        const p = playlistById.get(id.slice(3));
        return p ? coverSvg('pl' + p.id, p.name, `${p.songs.length} tracks`, 'playlist') : null;
    }
    const al = albumById.get(id) || albumById.get(songById.get(id)?.albumId);
    if (al) return coverSvg(al.id, al.name, al.artist, 'album');
    const a = artistById.get(id);
    return a ? coverSvg('artist' + a.id, a.name, '', 'artist') : null;
}

// ---------- silent audio ----------
function silentWav(seconds) {
    const rate = 8000;
    const n = Math.max(1, Math.floor(rate * seconds));
    const buf = Buffer.alloc(44 + n, 128);
    buf.write('RIFF', 0);
    buf.writeUInt32LE(36 + n, 4);
    buf.write('WAVEfmt ', 8);
    buf.writeUInt32LE(16, 16);
    buf.writeUInt16LE(1, 20);
    buf.writeUInt16LE(1, 22);
    buf.writeUInt32LE(rate, 24);
    buf.writeUInt32LE(rate, 28);
    buf.writeUInt16LE(1, 32);
    buf.writeUInt16LE(8, 34);
    buf.write('data', 36);
    buf.writeUInt32LE(n, 40);
    return buf;
}

