function settingsJs() {
    const salt = 'q8XkP2vLm4Rt';
    const server = {
        id: 'home-server',
        name: 'Home Server',
        type: 'subsonic',
        url: '__ORIGIN__',
        username: USER.username,
        userId: USER.username,
        isAdmin: true,
        savePassword: true,
        credential: `u=${USER.username}&s=${salt}&t=${md5(USER.password + salt)}`,
        version: '0.58.0 (local)',
        features: { lyricsMultipleStructured: [1], osFormPost: [1], serverPlayQueue: [1], topSongsByArtistId: [1] },
        musicFolderId: undefined,
        remoteUrl: '',
    };
    return `"use strict";
window.SERVER_URL = window.location.origin;
window.REMOTE_URL = "";
window.SERVER_NAME = "Home Server";
window.SERVER_TYPE = "subsonic";
window.SERVER_LOCK = "false";
window.LEGACY_AUTHENTICATION = "false";
window.ANALYTICS_DISABLED = "true";
(function () {
    // The web build calls api.github.com directly (update check / release notes). Point those
    // requests at the local stub so nothing leaves this machine.
    var open = XMLHttpRequest.prototype.open;
    XMLHttpRequest.prototype.open = function (method, url) {
        var args = Array.prototype.slice.call(arguments);
        if (typeof url === 'string' && url.indexOf('https://api.github.com/') === 0) {
            args[1] = '/_stub/github/' + url.slice('https://api.github.com/'.length);
        }
        return open.apply(this, args);
    };
})();
(function () {
    try {
        // Returning user: restore the saved session for this server the first time the app is opened.
        if (!localStorage.getItem('store_authentication')) {
            var server = ${JSON.stringify(server)};
            server.url = window.location.origin;
            localStorage.setItem('store_authentication', JSON.stringify({
                state: { currentServer: server, deviceId: 'b7Qm2cXr9LwTn4Ke', serverList: { 'home-server': server } },
                version: 2,
            }));
            localStorage.setItem('version', '"${APP_VERSION}"');
            localStorage.setItem('umami.disabled', '1');
        }
    } catch (e) {}
})();
`;
}

// ---------- GitHub API stub (Feishin release/update checks) ----------
const APP_VERSION = JSON.parse(readFileSync(join(HERE, '..', 'package.json'), 'utf8')).version;
const RELEASES = [
    [APP_VERSION, '2026-11-15T12:51:30Z', '## Fixes\n- Restore lyric lookup with missing artist metadata\n- Restore global search with selected Navidrome folders\n- Pass multiple Subsonic musicFolderIds on getRandomSongList\n\n## Features\n- Add refresh button to playlist sidebar'],
    ['1.16.2', '2026-10-28T18:02:11Z', '## Fixes\n- Fix queue drag-and-drop when the sidebar queue is collapsed\n- Fix crossfade stutter on gapless albums'],
    ['1.16.1', '2026-10-09T09:40:52Z', '## Fixes\n- Fix album artist links for multi-artist releases'],
    ['1.16.0', '2026-09-20T15:15:03Z', '## Features\n- Playlist folders in the sidebar\n- Structured lyrics with translations\n\n## Fixes\n- Many small UI fixes'],
].map(([v, d, body]) => ({ tag_name: 'v' + v, name: 'v' + v, published_at: d, prerelease: false, body, html_url: 'https://github.com/jeffvli/feishin/releases/tag/v' + v }));
function githubStub(path, body) {
    if (path.endsWith('/releases/latest')) return RELEASES[0];
    if (path.endsWith('/releases')) return RELEASES;
    if (path.includes('/compare/')) return { commits: [], total_commits: 0 };
    if (path === 'markdown') {
        let text = '';
        try { text = JSON.parse(body).text || ''; } catch {}
        return text.split('\n').map((l) => (l.startsWith('## ') ? `<h2>${esc(l.slice(3))}</h2>` : l.startsWith('- ') ? `<li>${esc(l.slice(2))}</li>` : l ? `<p>${esc(l)}</p>` : '')).join('');
    }
    return {};
}

// ---------- HTTP ----------
const MIME = { '.html': 'text/html; charset=utf-8', '.js': 'text/javascript', '.mjs': 'text/javascript', '.css': 'text/css', '.json': 'application/json', '.png': 'image/png', '.ico': 'image/x-icon', '.svg': 'image/svg+xml', '.webp': 'image/webp', '.woff2': 'font/woff2', '.woff': 'font/woff', '.ttf': 'font/ttf', '.wasm': 'application/wasm', '.webmanifest': 'application/manifest+json', '.map': 'application/json', '.gz': 'application/gzip', '.dat': 'application/octet-stream' };

function readBody(req) {
    return new Promise((resolve) => {
        const chunks = [];
        req.on('data', (c) => chunks.push(c));
        req.on('end', () => resolve(Buffer.concat(chunks).toString()));
    });
}
function toParams(sp) {
    const p = {};
    for (const [k, v] of sp) {
        if (k in p) p[k] = arr(p[k]).concat(v);
        else p[k] = v;
    }
    return p;
}
const send = (res, code, type, body, extra = {}) => {
    res.writeHead(code, { 'Content-Type': type, 'Access-Control-Allow-Origin': '*', ...extra });
    res.end(body);
};

const server = http.createServer(async (req, res) => {
    const url = new URL(req.url, 'http://localhost');
    if (req.method === 'OPTIONS') return send(res, 204, 'text/plain', '', { 'Access-Control-Allow-Headers': '*', 'Access-Control-Allow-Methods': 'GET,POST,OPTIONS' });

    if (url.pathname.startsWith('/rest/')) {
        let params = toParams(url.searchParams);
        if (req.method === 'POST') {
            const body = await readBody(req);
            const ct = req.headers['content-type'] || '';
            if (ct.includes('x-www-form-urlencoded')) params = { ...params, ...toParams(new URLSearchParams(body)) };
        }
        const name = url.pathname.slice(6).replace(/\.view$/, '');
        if (!checkAuth(params)) return send(res, 200, 'application/json', JSON.stringify(fail(40, 'Wrong username or password')));
        if (name === 'getCoverArt' || name === 'getAvatar') {
            const svg = coverFor(String(params.id || ''));
            if (!svg) return send(res, 404, 'text/plain', 'not found');
            return send(res, 200, 'image/svg+xml', svg, { 'Cache-Control': 'public, max-age=86400' });
        }
        if (name === 'stream' || name === 'download' || name === 'getTranscodeStream') {
            const s = songById.get(params.id || params.mediaId);
            const wav = silentWav(s ? s.duration : 5);
            return send(res, 200, 'audio/wav', wav, { 'Content-Length': wav.length, 'Accept-Ranges': 'none' });
        }
        const fn = api[name];
        if (!fn) console.log('unimplemented endpoint:', name);
        const result = fn ? fn(params) : fail(0, `Endpoint ${name} not implemented`);
        return send(res, 200, 'application/json', JSON.stringify(result));
    }

    if (url.pathname.startsWith('/_stub/github/')) {
        const body = req.method === 'POST' ? await readBody(req) : '';
        const r = githubStub(url.pathname.slice('/_stub/github/'.length), body);
        return typeof r === 'string' ? send(res, 200, 'text/html', r) : send(res, 200, 'application/json', JSON.stringify(r));
    }

    if (url.pathname.endsWith('/settings.js')) return send(res, 200, 'text/javascript', settingsJs(), { 'Cache-Control': 'no-store' });

    let file = normalize(join(WEB, decodeURIComponent(url.pathname)));
    if (!file.startsWith(WEB)) return send(res, 403, 'text/plain', 'forbidden');
    if (!existsSync(file) || statSync(file).isDirectory()) {
        if (existsSync(join(file, 'index.html'))) file = join(file, 'index.html');
        else file = join(WEB, 'index.html');
    }
    const type = MIME[extname(file)] || 'application/octet-stream';
    const cache = file.includes('/assets/') ? 'public, max-age=3600' : 'no-cache';
    send(res, 200, type, readFileSync(file), { 'Cache-Control': cache });
});

server.listen(PORT, '0.0.0.0', () => console.log(`Feishin + local OpenSubsonic stub on http://localhost:${PORT}/  (user ${USER.username})`));
